from collections import defaultdict

def mapreduce_agregasi(chunks):
    mapped = []
    for chunk in chunks:
        for kategori, nilai in chunk:
            mapped.append((kategori, float(nilai)))
    shuffled = defaultdict(list)
    for k, v in mapped:
        shuffled[k].append(v)
    reduced = {}
    for k in sorted(shuffled.keys()):
        vals = shuffled[k]
        reduced[k] = {'total': float(sum(vals)), 'count': len(vals)}
    return reduced

