def hitung_tarif_dinamis(jarak_km, permintaan, driver_tersedia, hujan=False):
    tarif_dasar = max(10000.0, 3000.0 * float(jarak_km))
    rasio = permintaan / max(driver_tersedia, 1)
    if rasio <= 1.0:
        mult = 1.0
    elif rasio <= 2.0:
        mult = 1.25
    else:
        mult = 1.5
    if hujan:
        mult = round(mult + 0.2, 2)
    tarif_akhir = round(tarif_dasar * mult, 2)
    return {'tarif_dasar': round(tarif_dasar, 2), 'multiplier': mult, 'tarif_akhir': tarif_akhir}

import numpy as np

def ramal_beban_pln(seri_mw, window=3):
    arr = np.asarray(seri_mw, dtype=float)
    if len(arr) < window:
        raise ValueError('Panjang seri harus >= window')
    errors = []
    for t in range(window, len(arr)):
        yhat = float(np.mean(arr[t - window:t]))
        errors.append(abs(arr[t] - yhat))
    pred_next = float(np.mean(arr[-window:]))
    mae = float(np.mean(errors)) if errors else 0.0
    return round(pred_next, 4), round(mae, 4)

