import numpy as np
from collections import Counter

def statistik_sesuai_skala(nilai, skala):
    s = skala.lower()
    modus = Counter(nilai).most_common(1)[0][0]
    if s == 'nominal':
        return {'modus': modus}
    arr = np.asarray(nilai, dtype=float)
    if s == 'ordinal':
        return {'modus': modus, 'median': float(np.median(arr))}
    if s in ('interval', 'rasio'):
        res = {
            'mean': float(np.mean(arr)),
            'std': float(np.std(arr, ddof=1)),
            'selisih_max_min': float(np.max(arr) - np.min(arr)),
        }
        if s == 'rasio':
            res['rasio_max_min'] = float(np.max(arr) / np.min(arr))
        return res
    raise ValueError('Skala tidak dikenal')

from scipy import stats

def uji_dua_kelompok(g1, g2, parametris=True, alpha=0.05):
    if parametris:
        res = stats.ttest_ind(g1, g2, equal_var=True)
    else:
        res = stats.mannwhitneyu(g1, g2, alternative='two-sided')
    p_val = float(res.pvalue)
    return {'stat': float(res.statistic), 'p_value': p_val, 'tolak_h0': bool(p_val < alpha)}

from scipy.stats import chi2_contingency

def uji_chi_square(tabel_kontingensi, alpha=0.05):
    chi2, p, dof, _ = chi2_contingency(tabel_kontingensi)
    return {'chi2': float(chi2), 'p_value': float(p), 'dof': int(dof), 'ada_hubungan': bool(p < alpha)}

