import pandas as pd

def binning_nilai(skor_list):
    labels = ['Kurang', 'Cukup', 'Baik', 'Sangat Baik']
    cats = pd.cut(skor_list, bins=[-0.01, 55, 70, 85, 100], labels=labels)
    counts = cats.value_counts()
    return {lbl: int(counts.get(lbl, 0)) for lbl in labels}

import math

def hitung_tfidf_manual(korpus, doc_idx, kata):
    tokens_list = [d.lower().split() for d in korpus]
    doc_tokens = tokens_list[doc_idx]
    if not doc_tokens:
        return 0.0
    df = sum(1 for toks in tokens_list if kata.lower() in toks)
    if df == 0:
        return 0.0
    tf = doc_tokens.count(kata.lower()) / len(doc_tokens)
    idf = math.log10(len(tokens_list) / df)
    return float(tf * idf)

import math

def hitung_perplexity(probabilitas_kata):
    n = len(probabilitas_kata)
    avg_neg_log = -sum(math.log(p) for p in probabilitas_kata) / n
    return float(math.exp(avg_neg_log))

import numpy as np

def morfologi_biner(img_bin, operasi='erosion'):
    arr = np.asarray(img_bin, dtype=int)
    h, w = arr.shape
    out = np.zeros((h, w), dtype=int)
    for i in range(1, h - 1):
        for j in range(1, w - 1):
            blok = arr[i - 1:i + 2, j - 1:j + 2]
            out[i, j] = int(np.min(blok)) if operasi == 'erosion' else int(np.max(blok))
    return out

import numpy as np

def median_filter_3x3(img_gray):
    arr = np.asarray(img_gray, dtype=float)
    h, w = arr.shape
    padded = np.pad(arr, 1, mode='edge')
    out = np.zeros((h, w), dtype=float)
    for i in range(h):
        for j in range(w):
            out[i, j] = float(np.median(padded[i:i + 3, j:j + 3]))
    return out

import numpy as np

def segmentasi_daun_hsv(rgb_img):
    arr = np.asarray(rgb_img, dtype=float) / 255.0
    h, w, _ = arr.shape
    mask = np.zeros((h, w), dtype=int)
    for i in range(h):
        for j in range(w):
            r, g, b = arr[i, j]
            cmax = max(r, g, b)
            cmin = min(r, g, b)
            delta = cmax - cmin
            if delta == 0:
                hue = 0.0
            elif cmax == r:
                hue = 60.0 * (((g - b) / delta) % 6.0)
            elif cmax == g:
                hue = 60.0 * (((b - r) / delta) + 2.0)
            else:
                hue = 60.0 * (((r - g) / delta) + 4.0)
            sat = (delta / cmax) if cmax > 0 else 0.0
            val = cmax
            if 70.0 <= hue <= 165.0 and sat >= 0.25 and val >= 0.20:
                mask[i, j] = 1
    return mask

import numpy as np

def perbaiki_kontras(img_gray):
    arr = np.asarray(img_gray, dtype=float)
    mn, mx = float(np.min(arr)), float(np.max(arr))
    if mx == mn:
        return np.zeros_like(arr, dtype=float)
    return ((arr - mn) / (mx - mn)) * 255.0

from collections import defaultdict

def spark_wordcount_partisi(partisi_teks, min_panjang=4):
    counts = defaultdict(int)
    for part in partisi_teks:
        for kalimat in part:
            for kata in kalimat.lower().split():
                if len(kata) >= min_panjang:
                    counts[kata] += 1
    return sorted(counts.items(), key=lambda x: (-x[1], x[0]))

