def lambda_serving_view(batch_totals, stream_events):
    view = {k: float(v) for k, v in batch_totals.items()}
    for prod, nom in stream_events:
        view[prod] = view.get(prod, 0.0) + float(nom)
    top = max(view, key=view.get) if view else None
    return view, top
